// Stage 1 - Accumulate. Append one queued research request as a JSON line to /data/batch-queue/pending.jsonl.
const fs = require('fs');
const path = require('path');

const queueDir = '/data/batch-queue';
const pendingFile = path.join(queueDir, 'pending.jsonl');

// Ensure the queue directory exists (mkdir -p).
fs.mkdirSync(queueDir, { recursive: true });

const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const query = (body.query || '').toString().trim();
if (!query) {
  return [{ json: { queued: false, error: 'missing query' } }];
}

// Build a stable custom_id (slug + timestamp) if the caller did not supply one.
function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);
}
const now = new Date();
const stamp = now.toISOString().replace(/[:.]/g, '-');
const customId = (body.custom_id && body.custom_id.toString().trim())
  ? body.custom_id.toString().trim()
  : (slugify(query) + '-' + stamp);

const record = {
  custom_id: customId,
  query: query,
  system: (body.system || '').toString(),
  queued_at: now.toISOString()
};

fs.appendFileSync(pendingFile, JSON.stringify(record) + '\n');

return [{ json: { queued: true, custom_id: customId } }];

// Stage 2a - Read the day's accumulated queue and build the Message Batches requests array.
const fs = require('fs');
const path = require('path');

const queueDir = '/data/batch-queue';
const pendingFile = path.join(queueDir, 'pending.jsonl');

if (!fs.existsSync(pendingFile)) {
  return [{ json: { empty: true, reason: 'no pending file', requests: [] } }];
}

const raw = fs.readFileSync(pendingFile, 'utf8');
const lines = raw.split('\n').map(l => l.trim()).filter(l => l.length > 0);

if (lines.length === 0) {
  return [{ json: { empty: true, reason: 'pending file empty', requests: [] } }];
}

const requests = [];
const destinationMap = {};

for (const line of lines) {
  let rec;
  try {
    rec = JSON.parse(line);
  } catch (e) {
    continue; // skip malformed lines rather than fail the whole batch
  }
  if (!rec.custom_id || !rec.query) continue;

  const params = {
    model: 'claude-sonnet-4-6',
    max_tokens: 4096,
    messages: [
      { role: 'user', content: rec.query }
    ]
  };
  if (rec.system && rec.system.length > 0) {
    params.system = rec.system;
  }

  requests.push({ custom_id: rec.custom_id, params: params });
  destinationMap[rec.custom_id] = rec.dest || null;
}

if (requests.length === 0) {
  return [{ json: { empty: true, reason: 'no valid requests', requests: [] } }];
}

return [{ json: { empty: false, count: requests.length, requests: requests, destination_map: destinationMap } }];

// Stage 2b - Persist the returned batch id + custom_id-to-destination map, then archive and clear pending.jsonl.
const fs = require('fs');
const path = require('path');

const queueDir = '/data/batch-queue';
const submittedDir = path.join(queueDir, 'submitted');
const archiveDir = path.join(queueDir, 'archive');
const pendingFile = path.join(queueDir, 'pending.jsonl');

fs.mkdirSync(submittedDir, { recursive: true });
fs.mkdirSync(archiveDir, { recursive: true });

// The batch object returned by the Anthropic API.
const resp = $json;
const batchId = resp.id || ('unknown-' + Date.now());

// The destination map was built upstream; pull it from the 'Build batch requests' node.
let destinationMap = {};
try {
  destinationMap = $('Build batch requests').first().json.destination_map || {};
} catch (e) {
  destinationMap = {};
}

const submittedRecord = {
  batch_id: batchId,
  processing_status: resp.processing_status || null,
  submitted_at: new Date().toISOString(),
  results_url: resp.results_url || null,
  custom_id_destinations: destinationMap
};

fs.writeFileSync(
  path.join(submittedDir, batchId + '.json'),
  JSON.stringify(submittedRecord, null, 2)
);

// Archive the day's queue, then clear pending.jsonl so tomorrow starts clean.
if (fs.existsSync(pendingFile)) {
  const dateStamp = new Date().toISOString().slice(0, 10);
  const archivePath = path.join(archiveDir, dateStamp + '.jsonl');
  fs.copyFileSync(pendingFile, archivePath);
  fs.writeFileSync(pendingFile, '');
}

return [{ json: { stored: true, batch_id: batchId } }];
